function rows(){return Object.values(cache).flatMap(x=>x[tab]||[]).filter(x=>x.active).filter(x=>!selectedRegion||x.region===selectedRegion).filter(x=>JSON.stringify(x).toLowerCase().includes(query.toLowerCase()))}function peopleRows(){return Object.values(cache).flatMap(x=>x.people||[]).filter(x=>!selectedRegion||x.region===selectedRegion).filter(x=>personType==='all'||(x.person_type||'staff')===personType).filter(x=>statusFilter==='all'||(statusFilter==='active'?x.active!==false:x.active===false)).filter(x=>JSON.stringify(x).toLowerCase().includes(query.toLowerCase()))}
function teamName(id){for(const x of Object.values(cache)){const t=x.teams.find(t=>t.id===id);if(t)return t.name}return '—'}
// Keep the spreadsheet model independent of the operational roster's normalized fields.
const sourceHeaders=['#','القطاع','المنطقة','المهندس','المشرف','رقم الفريق','الرقم الوظيفي','رقم الاقامه','الإسم','الوظيفة','تقيم الفنى','حالة التيم','التصنيف','رقم السياره','نوع السيارة','مالك السيارة','الجنسية','مصدر العمالة','تاريخ المباشرة','رقم التليفون','ملاحظات','المدير','الرقم الوظيفي للمدير'];
const sourceGrid={filters:{},sort:-1,direction:1,widths:[],page:0,pageSize:50,filtersOpen:false,values:{},cross:{},offices:null,projectRegions:null,card:null};
try{const saved=JSON.parse(localStorage.getItem('fm-workforce-column-widths-v1')||'[]');if(Array.isArray(saved))sourceGrid.widths=saved.map(v=>Math.max(64,Math.min(720,Number(v)||180)))}catch{}
const gridText=v=>String(v??'').normalize('NFKC').replace(/[٠-٩]/g,c=>String(c.charCodeAt(0)-1632)).replace(/[۰-۹]/g,c=>String(c.charCodeAt(0)-1776)).replace(/٬/g,',').replace(/٫/g,'.').toLocaleLowerCase().trim();
const gridCollator=new Intl.Collator('ar',{numeric:true,sensitivity:'base'});
function compareGridValues(a,b){const x=gridText(a),y=gridText(b);if(!x||!y)return !x&&!y?0:!x?1:-1;const num=v=>/^[+-]?[\d,]+(?:\.\d+)?$/.test(v)?Number(v.replace(/,/g,'')):NaN,n=num(x),m=num(y);if(Number.isFinite(n)&&Number.isFinite(m))return n-m;return gridCollator.compare(x,y)}
function applySourceGrid(records,skipColumn=null,skipCross=null,skipOffice=false,skipCard=false){let a=records.filter(x=>Object.entries(sourceGrid.filters).every(([i,q])=>Number(i)===skipColumn||gridText(x.values[i]).includes(gridText(q)))&&Object.entries(sourceGrid.values).every(([i,values])=>Number(i)===skipColumn||values.includes(String(x.values[i]??'')))&&matchesChartSelection(x,skipCross)&&matchesCardFilter(x,skipCard)&&(!sourceGrid.offices||skipOffice||recordOffices(x).some(v=>sourceGrid.offices.includes(v))));if(sourceGrid.sort>=0){a=a.map((x,i)=>({x,i})).sort((a,b)=>{const x=a.x.values[sourceGrid.sort],y=b.x.values[sourceGrid.sort];if(!gridText(x)||!gridText(y))return compareGridValues(x,y)||a.i-b.i;return sourceGrid.direction*compareGridValues(x,y)||a.i-b.i}).map(v=>v.x)}return a}
function sourcePageRows(){const all=sourceModelRows();sourceGrid.page=Math.max(0,Math.min(sourceGrid.page,Math.max(0,Math.ceil(all.length/sourceGrid.pageSize)-1)));return all.slice(sourceGrid.page*sourceGrid.pageSize,(sourceGrid.page+1)*sourceGrid.pageSize)}
function sourceGridFooter(){const total=sourceModelRows().length,pages=Math.max(1,Math.ceil(total/sourceGrid.pageSize)),first=total?sourceGrid.page*sourceGrid.pageSize+1:0,last=Math.min(total,(sourceGrid.page+1)*sourceGrid.pageSize);return `<div class="fm341-grid-footer"><span>عرض ${first.toLocaleString('ar-SA')}–${last.toLocaleString('ar-SA')} من ${total.toLocaleString('ar-SA')} صف</span><div class="fm341-pages"><label>صفوف الصفحة <select data-grid-page-size>${[50,100,250,5000].map(n=>`<option value="${n}" ${n===sourceGrid.pageSize?'selected':''}>${n===5000?'الكل':n}</option>`).join('')}</select></label><button type="button" data-grid-prev ${sourceGrid.page===0?'disabled':''}>السابق</button><span class="fm341-page-label">${sourceGrid.page+1} / ${pages}</span><button type="button" data-grid-next ${sourceGrid.page>=pages-1?'disabled':''}>التالي</button></div></div>`}
