function titleText(value){return String(value??'').normalize('NFKC').replace(/[\u00A0\u2007\u202F]/g,' ').replace(/\s+/g,' ').trim()}
function jobTitleKey(value){return titleText(value).replace(/[أإآ]/g,'ا').replace(/ى/g,'ي').replace(/[\u064B-\u065F\u0670\u0640]/g,'').replace(/\s*\+\s*/g,' + ').replace(/\s*\(\s*/g,' (').replace(/\s*\)/g,')').toLowerCase()}
function normalizeJobTitle(value){const clean=titleText(value);return approvedJobTitleMap.get(jobTitleKey(clean))||clean}
function normalizedSourceValues(values){const copy=[...values];copy[9]=normalizeJobTitle(copy[9]);return copy}
function titleMigrationPreview(){const regions={},changes=new Map();let total=0;for(const r of Object.keys(cache)){if(cache[r].sourceUnavailable)continue;const snapshot=sourceSnapshot(r);let regionChanged=false;const rows=snapshot.rows.map(values=>{const next=correctedOrganizationValues(normalizedSourceValues(values),r);let rowChanged=false;for(const [index,label] of [[9,'المسمى الوظيفي'],[12,'التصنيف'],[21,'المسؤول المباشر'],[22,'الرقم الوظيفي للمسؤول']]){if(String(values[index]??'')===String(next[index]??''))continue;rowChanged=true;regionChanged=true;const from=String(values[index]??''),to=String(next[index]??''),key=label+'\u0000'+from+'\u0000'+to,item=changes.get(key)||{field:label,from,to,count:0};item.count++;changes.set(key,item)}if(rowChanged)total++;return next});if(regionChanged)regions[r]={rows,revision:snapshot.revision}}return {regions,changes:[...changes.values()],total}}
function saveApprovedTitles(parent){let preview;try{preview=titleMigrationPreview()}catch(e){root.showToast?.(e.message,'error');return}const d=dialog('توحيد المسميات والتصنيف'),body=d.querySelector('[data-body]');body.innerHTML=`<p>سيتم حفظ التعديلات المعتمدة لعدد <b>${preview.total.toLocaleString('ar-SA')}</b> صف، للمسميات والتصنيفات والربط الإداري المعتمد، بدون حذف أي صف.</p><p>المسميات غير الموجودة في جدول التحويل تبقى كما هي.</p><div class="fm334-table-wrap"><table><thead><tr><th>الحقل</th><th>القيمة الحالية</th><th>القيمة المعتمدة</th><th>الصفوف</th></tr></thead><tbody>${preview.changes.map(x=>`<tr><td>${E(x.field)}</td><td>${E(x.from)}</td><td>${E(x.to)}</td><td>${x.count}</td></tr>`).join('')||'<tr><td colspan="4">كل المسميات والتصنيفات المحفوظة مطابقة حاليًا.</td></tr>'}</tbody></table></div><p data-title-save-error role="alert"></p><div class="fm345-title-actions"><button data-cancel-title-save>إغلاق</button><button data-confirm-title-save class="primary" ${preview.total?'':'disabled'}>حفظ المسميات والتصنيف</button></div>`;body.querySelector('[data-cancel-title-save]').onclick=()=>d.close();body.querySelector('[data-confirm-title-save]').onclick=async event=>{event.target.disabled=true;try{await rpc('fm_workforce339_source_save',{p:{regions:preview.regions}});lastSourceDeletion=null;d.close();await load(parent);root.showToast?.('تم حفظ المسميات والتصنيفات المعتمدة','success')}catch(e){body.querySelector('[data-title-save-error]').textContent=e.message;event.target.disabled=false}};d.showModal()}

