function assignedTeam(row){const p=recordPerson(row),data=cache[row.region]||{};return (data.teams||[]).find(t=>t.id===p.team_id||String(t.code||t.name||'').replace(/^فريق\s*/,'')===String(row.values[5]||'').replace(/^فريق\s*/,''))}
