 const people=dashboardPeople().filter(x=>x.active),locations=locationBreakdown(people),categories=Object.keys(workforcePalette).filter(c=>people.some(p=>workforceCategory(p)===c)),fmt=n=>new Intl.NumberFormat('ar-SA').format(n),percent=workforceView.region==='percent';
